insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','bedbugs','Stripping a bed, you spot tiny dark spots and a small reddish bug on the mattress seam. What do you do?','Al quitar las sábanas ves puntitos oscuros y un bichito rojizo en la costura del colchón. ¿Qué haces?','["Stop, leave everything in place, close the door and tell your supervisor right away", "Finish cleaning and mention it at end of shift", "Move the linens to the next room", "Spray it with glass cleaner"]'::jsonb,'["Detenerte, dejar todo como está, cerrar la puerta y avisarle a tu supervisora de inmediato", "Terminar de limpiar y comentarlo al final del turno", "Llevar la ropa de cama al siguiente cuarto", "Rociarlo con limpiavidrios"]'::jsonb,0,'Possible bed bugs: don''t carry linens out and spread them. Isolate the room so it can be inspected.','Si pueden ser chinches, no saques la ropa de cama para no regarlas. Aísla el cuarto para que lo revisen.','https://www.cdc.gov/bed-bugs/about/index.html',array['hk_supervisor','room_attendant']::text[],'role','med',array['bedbugs','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','bedbugs','Where do bed bugs most often hide in a guest room?','¿Dónde se esconden más seguido las chinches en un cuarto?','["Mattress seams, box spring and headboard", "In the shower drain", "Inside the minifridge", "On the ceiling light"]'::jsonb,'["En las costuras del colchón, la base y la cabecera", "En la coladera de la regadera", "Dentro del minirefrigerador", "En la lámpara del techo"]'::jsonb,0,'Bed bugs stay close to where people sleep: seams, tags, box springs and headboards.','Las chinches se quedan cerca de donde duermen las personas: costuras, etiquetas, bases y cabeceras.','https://www.cdc.gov/bed-bugs/about/index.html',array['hk_supervisor','room_attendant']::text[],'role','hard',array['bedbugs','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sharps','You find a used needle in the bedding. What''s the safe move?','Encuentras una aguja usada entre las sábanas. ¿Qué es lo seguro?','["Pick it up carefully and toss it in the trash", "Put the cap back on", "Don''t touch it — keep others away and call your supervisor for the sharps kit", "Wrap it in a towel"]'::jsonb,'["Recogerla con cuidado y tirarla a la basura", "Ponerle la tapa", "No tocarla; alejar a los demás y llamar a tu supervisora para el kit de objetos punzantes", "Envolverla en una toalla"]'::jsonb,2,'Needles can carry bloodborne disease. Only trained staff with a sharps container and gloves should handle them.','Las agujas pueden transmitir enfermedades por sangre. Solo personal capacitado con guantes y contenedor especial debe manejarlas.','https://www.osha.gov/bloodborne-pathogens',array['hk_supervisor','room_attendant']::text[],'role','easy',array['sharps','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','blood','There''s blood on the sheets. What do you wear before handling them?','Hay sangre en las sábanas. ¿Qué te pones antes de tocarlas?','["Only an apron", "Disposable gloves, and bag the linen separately per policy", "Oven mitts", "Nothing, just wash hands after"]'::jsonb,'["Solo un mandil", "Guantes desechables, y poner la ropa en bolsa aparte según la política", "Guantes de cocina", "Nada, solo lavarte las manos después"]'::jsonb,1,'Treat blood as potentially infectious: gloves on, and follow the hotel''s soiled-linen procedure.','Trata la sangre como posible fuente de infección: ponte guantes y sigue el procedimiento para ropa sucia.','https://www.osha.gov/bloodborne-pathogens',array['hk_supervisor','room_attendant']::text[],'role','med',array['blood','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','A spray bottle on your cart has no label. What do you do?','Una botella de tu carrito no tiene etiqueta. ¿Qué haces?','["Use it on glass only", "Don''t use it — give it to your supervisor to label or dispose of", "Mix it with water and use it", "Smell it to figure out what it is"]'::jsonb,'["Usarla solo en vidrios", "No usarla; dársela a tu supervisora para etiquetarla o desecharla", "Mezclarla con agua y usarla", "Olerla para saber qué es"]'::jsonb,1,'OSHA requires chemical containers to be labeled so you know the hazards. Unknown chemicals don''t get used.','OSHA exige que los químicos estén etiquetados para conocer sus riesgos. Lo que no se sabe qué es, no se usa.','https://www.osha.gov/hazcom',array['hk_supervisor','room_attendant']::text[],'role','med',array['chemicals','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','A cleaner splashes in your eye. What do you do first?','Un limpiador te salpica en el ojo. ¿Qué haces primero?','["Rub it", "Flush with clean water right away, then check the SDS and report it", "Put lotion on it", "Wait to see if it stops burning"]'::jsonb,'["Tallarte el ojo", "Enjuagarte con agua limpia de inmediato, luego revisar la SDS y reportarlo", "Ponerte crema", "Esperar a ver si deja de arder"]'::jsonb,1,'Every chemical has a Safety Data Sheet with first-aid steps. Flush first, then report.','Cada químico tiene su hoja de seguridad (SDS) con primeros auxilios. Primero enjuaga y luego reporta.','https://www.osha.gov/hazcom',array['hk_supervisor','room_attendant']::text[],'role','med',array['chemicals','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','What''s the safest way to lift a heavy mattress corner to tuck sheets?','¿Cuál es la forma más segura de levantar la esquina de un colchón pesado para meter las sábanas?','["Lift with one hand", "Bend at the waist and pull fast", "Twist while lifting", "Bend your knees, keep your back straight and use your legs"]'::jsonb,'["Levantar con una sola mano", "Doblarte de la cintura y jalar rápido", "Girar mientras levantas", "Doblar las rodillas, mantener la espalda recta y hacer fuerza con las piernas"]'::jsonb,3,'Using your legs and not twisting protects your back on every bed, every day.','Usar las piernas y no girar protege tu espalda en cada cama, todos los días.','https://www.osha.gov/ergonomics',array['hk_supervisor','room_attendant']::text[],'role','easy',array['ergonomics','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','Your cart is overloaded and hard to push. Best fix?','Tu carrito está sobrecargado y cuesta empujarlo. ¿Qué es lo mejor?','["Kick it to get it rolling", "Pull it behind you", "Ask a guest to help", "Unload some and make an extra trip — push, don''t pull"]'::jsonb,'["Patearlo para que avance", "Jalarlo detrás de ti", "Pedirle ayuda a un huésped", "Bajarle cosas y dar otra vuelta; empújalo, no lo jales"]'::jsonb,3,'A reasonable load you push is easier on your body and lets you see where you''re going.','Empujar una carga razonable cuida tu cuerpo y te deja ver por dónde vas.','https://www.osha.gov/ergonomics',array['hk_supervisor','room_attendant']::text[],'role','med',array['ergonomics','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','privacy','A room has the Do Not Disturb sign up at checkout time. What do you do?','Un cuarto tiene el letrero de No Molestar a la hora de salida. ¿Qué haces?','["Don''t knock or enter; let the front desk or supervisor follow up", "Enter quietly to check", "Knock loudly until they answer", "Skip it and never report it"]'::jsonb,'["No tocar ni entrar; que la recepción o tu supervisora le den seguimiento", "Entrar despacito a revisar", "Tocar fuerte hasta que contesten", "Saltarlo y no reportarlo"]'::jsonb,0,'Respect the sign, but report it so the hotel can do a welfare check per policy.','Respeta el letrero, pero repórtalo para que el hotel haga una revisión de bienestar según la política.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['privacy','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','privacy','A guest left their laptop open with banking on the screen. What do you do?','Un huésped dejó su laptop abierta con su banco en la pantalla. ¿Qué haces?','["Take a photo for security", "Don''t touch or read it; clean around it", "Close it to protect it", "Move it to the closet"]'::jsonb,'["Tomarle foto para seguridad", "No tocarla ni leerla; limpiar alrededor", "Cerrarla para protegerla", "Guardarla en el clóset"]'::jsonb,1,'Guest belongings and information are private. Clean around personal items without handling them.','Las cosas y la información del huésped son privadas. Limpia alrededor sin tocarlas.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['privacy','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','Someone in the hallway says it''s their room and asks you to let them in. What do you do?','Alguien en el pasillo dice que es su cuarto y te pide que le abras. ¿Qué haces?','["Politely send them to the front desk for a new key", "Lend them your master key", "Open it if they know the room number", "Open it since they seem nice"]'::jsonb,'["Mandarlo amablemente a recepción por una llave nueva", "Prestarle tu llave maestra", "Abrirle si sabe el número de cuarto", "Abrirle porque se ve buena gente"]'::jsonb,0,'Never open a room for anyone. The desk verifies ID — that protects the real guest.','Nunca le abras un cuarto a nadie. Recepción verifica la identificación, así se protege al huésped real.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['security','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','You lost your master key card during your shift. When do you report it?','Perdiste tu tarjeta llave maestra durante el turno. ¿Cuándo lo reportas?','["Immediately, so it can be deactivated", "No need, it''s just a card", "At the end of the week", "Only if you can''t find it by tomorrow"]'::jsonb,'["De inmediato, para que la desactiven", "No hace falta, es solo una tarjeta", "Al final de la semana", "Solo si mañana no aparece"]'::jsonb,0,'A lost master opens every room. Fast reporting lets the desk cancel it right away.','Una maestra perdida abre todos los cuartos. Reportarla rápido permite cancelarla de inmediato.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['security','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trafficking','Which pattern could be a sign of human trafficking in a room?','¿Qué situación podría ser señal de trata de personas en un cuarto?','["Many different visitors, DND for days, and a guest who seems controlled or scared", "Takeout containers in the trash", "A business traveler with a laptop", "A family with kids'' toys"]'::jsonb,'["Muchas visitas distintas, No Molestar por días y alguien que parece controlado o con miedo", "Envases de comida en la basura", "Un viajero de negocios con laptop", "Una familia con juguetes de niños"]'::jsonb,0,'Don''t confront anyone. Note what you saw and tell your manager — they decide whether to call police.','No confrontes a nadie. Anota lo que viste y avísale a tu gerente; ellos deciden si llaman a la policía.','https://www.dhs.gov/blue-campaign',array['hk_supervisor','room_attendant']::text[],'role','hard',array['trafficking','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lostfound','You find a wedding ring by the sink in a checked-out room. What''s right?','Encuentras un anillo de boda junto al lavabo en un cuarto ya desocupado. ¿Qué es lo correcto?','["Leave it on the counter", "Keep it if no one calls in a day", "Give it to a coworker", "Turn it in to lost and found with the room number, date and time"]'::jsonb,'["Dejarlo en el lavabo", "Quedártelo si nadie llama en un día", "Dárselo a un compañero", "Entregarlo a objetos perdidos con número de cuarto, fecha y hora"]'::jsonb,3,'Logging lost items with details helps return them and protects you.','Registrar los objetos perdidos con detalles ayuda a devolverlos y te protege a ti.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['lostfound','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','In what order should you clean a bathroom to avoid spreading germs?','¿En qué orden debes limpiar un baño para no regar gérmenes?','["Cleanest to dirtiest — mirror and sink first, toilet last", "Floor first, then counters", "Any order is fine", "Toilet first, then sink with the same cloth"]'::jsonb,'["De lo más limpio a lo más sucio: espejo y lavabo primero, el inodoro al final", "El piso primero y luego las barras", "Cualquier orden sirve", "El inodoro primero y luego el lavabo con el mismo trapo"]'::jsonb,0,'Working clean to dirty, with separate cloths, keeps toilet germs off sinks and glasses.','Trabajar de limpio a sucio, con trapos separados, evita llevar gérmenes del inodoro al lavabo.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['cleaning','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','Why use color-coded cloths, like one color only for toilets?','¿Para qué sirven los trapos de colores, como uno solo para inodoros?','["Because they look nicer", "So guests know you cleaned", "So toilet cloths never touch sinks, cups or counters", "To save detergent"]'::jsonb,'["Porque se ven más bonitos", "Para que el huésped sepa que limpiaste", "Para que los trapos del inodoro nunca toquen lavabos, vasos ni barras", "Para ahorrar detergente"]'::jsonb,2,'Color coding is a simple way to stop cross-contamination.','Usar colores es una forma sencilla de evitar la contaminación cruzada.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['cleaning','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','A disinfectant label says 10-minute contact time. What does that mean?','La etiqueta de un desinfectante dice 10 minutos de contacto. ¿Qué significa?','["Wipe it within 10 seconds", "It expires in 10 minutes", "The surface must stay wet that long to kill germs before wiping", "Rinse after 10 minutes no matter what"]'::jsonb,'["Secarlo en 10 segundos", "Caduca en 10 minutos", "La superficie debe quedar mojada ese tiempo para matar gérmenes antes de secar", "Enjuagar a los 10 minutos, pase lo que pase"]'::jsonb,2,'Wiping too soon means the disinfectant didn''t finish working.','Si secas antes, el desinfectante no terminó de hacer su efecto.','https://www.epa.gov/pesticide-registration/selected-eparegistered-disinfectants',array['hk_supervisor','room_attendant']::text[],'role','med',array['cleaning','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','Which high-touch item do guests notice most when it''s dirty?','¿Qué cosa que se toca mucho notan más los huéspedes cuando está sucia?','["The back of the closet", "The ceiling", "The fire sprinkler", "The TV remote — wipe it every room"]'::jsonb,'["El fondo del clóset", "El techo", "El rociador contra incendios", "El control de la tele: límpialo en cada cuarto"]'::jsonb,3,'Remotes, light switches, handles and phones are high-touch spots to disinfect every time.','Controles, apagadores, manijas y teléfonos se tocan mucho y hay que desinfectarlos siempre.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['cleaning','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','maintenance','The bathroom fan is loud and rattling. What do you do?','El extractor del baño hace mucho ruido. ¿Qué haces?','["Turn off the breaker", "Try to fix it yourself with a knife", "Report it to maintenance with a work order before the next guest", "Ignore it"]'::jsonb,'["Bajar el breaker", "Intentar arreglarlo con un cuchillo", "Reportarlo a mantenimiento con una orden de trabajo antes del siguiente huésped", "Ignorarlo"]'::jsonb,2,'You''re the eyes of the hotel. Reporting small issues keeps rooms sellable and guests happy.','Tú eres los ojos del hotel. Reportar detalles mantiene los cuartos vendibles y a los huéspedes contentos.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['maintenance','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','maintenance','There''s water on the floor under the sink. What''s needed?','Hay agua en el piso debajo del lavabo. ¿Qué se necesita?','["Dry it, put up a wet-floor sign and report a possible leak to maintenance", "Put a towel down and leave it", "Just mop it", "Tell the next guest"]'::jsonb,'["Secarla, poner letrero de piso mojado y reportar posible fuga a mantenimiento", "Poner una toalla y dejarla", "Solo trapear", "Decirle al siguiente huésped"]'::jsonb,0,'Leaks get worse and cause slips. Clean up, warn, and report.','Las fugas empeoran y provocan resbalones. Limpia, avisa y reporta.','https://www.osha.gov/walking-working-surfaces',array['hk_supervisor','room_attendant']::text[],'role','med',array['maintenance','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','guest','A guest asks you for extra towels while you''re in the hall. Best response?','Un huésped te pide toallas extra mientras estás en el pasillo. ¿Qué es lo mejor?','["Tell them to call the desk", "Say you''re busy", "Smile and hand them over from your cart, or bring them quickly", "Point to the laundry room"]'::jsonb,'["Decirle que llame a recepción", "Decirle que estás ocupada", "Sonreír y dárselas de tu carrito o llevárselas rápido", "Señalarle la lavandería"]'::jsonb,2,'Small, quick yeses make big impressions on guest reviews.','Los pequeños "sí" rápidos causan gran impresión en las reseñas.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['guest','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','What do you do with drinking glasses in a stayover room?','¿Qué haces con los vasos en un cuarto ocupado (stayover)?','["Swap them for clean, sealed glasses per standard", "Leave the used ones", "Rinse them in the bathroom sink", "Dry them with the bath towel"]'::jsonb,'["Cambiarlos por vasos limpios y sellados según el estándar", "Dejar los usados", "Enjuagarlos en el lavabo", "Secarlos con la toalla de baño"]'::jsonb,0,'Glasses should never be washed in a guest bathroom — swap them for clean ones.','Los vasos nunca se lavan en el baño del cuarto; se cambian por limpios.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','hard',array['cleaning','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','A guest''s pet is loose in a room you need to clean. What do you do?','La mascota de un huésped anda suelta en el cuarto que vas a limpiar. ¿Qué haces?','["Feed it", "Don''t enter; note it and let the desk contact the guest", "Take it to the lobby", "Go in and shoo it into the bathroom"]'::jsonb,'["Darle de comer", "No entrar; anotarlo y que recepción contacte al huésped", "Llevarla al lobby", "Entrar y meterla al baño"]'::jsonb,1,'For your safety and the pet''s, wait until the guest is there or the pet is crated.','Por tu seguridad y la de la mascota, espera a que el huésped esté o que la mascota esté en su jaula.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['safety','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','It''s January and a guest room is freezing with the window cracked open. What do you do?','Es enero y un cuarto está helado con la ventana entreabierta. ¿Qué haces?','["Close the window, set the thermostat to standard and report it if the heat isn''t working", "Leave it, the guest wanted it", "Open it more to air it out", "Turn on the oven"]'::jsonb,'["Cerrar la ventana, poner el termostato en el estándar y reportar si la calefacción no sirve", "Dejarla, así la quería el huésped", "Abrirla más para ventilar", "Prender el horno"]'::jsonb,0,'Minnesota cold can freeze pipes near windows. Close it and report heating problems.','El frío de Minnesota puede congelar tuberías cerca de las ventanas. Ciérrala y reporta fallas de calefacción.','https://www.osha.gov/winter-weather',array['hk_supervisor','room_attendant']::text[],'role','easy',array['winter','housekeeping']::text[],null,'11-15','03-15',null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','inspection','A room fails inspection for hair in the tub. Best approach with the attendant?','Un cuarto no pasa la inspección por pelos en la tina. ¿Cómo lo manejas con la recamarista?','["Show them privately, have it fixed, and coach on the checklist", "Call them out in the hallway", "Write them up for the first miss", "Fix it yourself and say nothing"]'::jsonb,'["Mostrárselo en privado, que lo corrija y repasar la lista de revisión", "Llamarle la atención en el pasillo", "Levantarle un reporte a la primera", "Arreglarlo tú y no decir nada"]'::jsonb,0,'Private, specific coaching fixes the habit without embarrassing anyone.','Corregir en privado y con detalles cambia el hábito sin avergonzar a nadie.','general hospitality best practice',array['hk_supervisor']::text[],'role','med',array['inspection','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','inspection','Which rooms should be inspected first?','¿Qué cuartos se deben inspeccionar primero?','["Rooms with DND", "The room farthest from the elevator", "Whatever is on the top floor", "Rooms needed for early arrivals or VIPs"]'::jsonb,'["Los cuartos con No Molestar", "El cuarto más lejos del elevador", "Lo que esté en el último piso", "Los que se necesitan para llegadas tempranas o VIPs"]'::jsonb,3,'Prioritize what the front desk needs to sell or assign soon.','Prioriza lo que recepción necesita vender o asignar pronto.','general hospitality best practice',array['hk_supervisor']::text[],'role','med',array['inspection','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','staffing','Two attendants called out and checkouts are high. What''s the best first move?','Dos recamaristas faltaron y hay muchas salidas. ¿Qué es lo primero que conviene hacer?','["Wait and see", "Clean stayovers first", "Tell everyone to rush and skip inspections", "Prioritize arrivals and checkouts, tell the GM and front desk, and split boards fairly"]'::jsonb,'["Esperar a ver qué pasa", "Limpiar primero los stayovers", "Decirle a todos que se apuren y no inspeccionar", "Priorizar llegadas y salidas, avisar al gerente y a recepción, y repartir los cuartos de forma justa"]'::jsonb,3,'Communicate early and focus on the rooms the hotel needs to sell today.','Comunica temprano y enfócate en los cuartos que el hotel necesita vender hoy.','general hospitality best practice',array['hk_supervisor']::text[],'role','hard',array['staffing','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','An attendant says their back hurts after lifting a mattress. What do you do?','Una recamarista dice que le duele la espalda después de levantar un colchón. ¿Qué haces?','["Have them stop, report the injury to the manager and document it the same day", "Wait to report until it gets worse", "Give them painkillers", "Tell them to keep going"]'::jsonb,'["Que se detenga, reportar la lesión al gerente y documentarla el mismo día", "Esperar a reportarlo hasta que empeore", "Darle pastillas para el dolor", "Decirle que siga"]'::jsonb,0,'Work injuries must be reported promptly so the employee gets proper care.','Las lesiones de trabajo se reportan a tiempo para que la persona reciba atención.','https://www.dli.mn.gov/workers-compensation',array['hk_supervisor']::text[],'role','med',array['safety','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','inventory','What do linen par levels tell you?','¿Qué te dicen los niveles par de ropa de cama?','["How many stains are allowed", "How many sets you need on hand across rooms, laundry and shelves to run smoothly", "The towel color", "How many a guest can take home"]'::jsonb,'["Cuántas manchas se permiten", "Cuántos juegos se necesitan entre cuartos, lavandería y anaqueles para operar bien", "El color de las toallas", "Cuántas puede llevarse un huésped"]'::jsonb,1,'Running below par means rooms wait on linen. Track it and order before you''re short.','Estar por debajo del par hace que los cuartos esperen ropa. Llévalo controlado y pide antes de que falte.','general hospitality best practice',array['hk_supervisor']::text[],'role','med',array['inventory','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','Why should laundry chemicals never be mixed by hand, like bleach with ammonia?','¿Por qué nunca se deben mezclar a mano químicos de lavandería, como cloro con amoniaco?','["They stop cleaning", "They make the machine louder", "They can release toxic gas", "They turn the water blue"]'::jsonb,'["Dejan de limpiar", "Hacen más ruido en la máquina", "Pueden soltar un gas tóxico", "Pintan el agua de azul"]'::jsonb,2,'Bleach plus ammonia or acids makes dangerous gases. Use only the dispensing system.','El cloro con amoniaco o ácidos produce gases peligrosos. Usa solo el sistema dosificador.','https://www.osha.gov/hazcom',array['laundry']::text[],'role','med',array['chemicals','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','What should you clean before every dryer load or at least every shift?','¿Qué debes limpiar antes de cada carga de secadora o al menos cada turno?','["The control label", "The outside paint", "The floor drain", "The lint screen"]'::jsonb,'["La etiqueta de controles", "La pintura de afuera", "La coladera del piso", "El filtro de pelusa"]'::jsonb,3,'Lint buildup is a leading cause of dryer fires.','La pelusa acumulada es una de las principales causas de incendios en secadoras.','https://www.cpsc.gov/Safety-Education/Safety-Education-Centers/Clothes-Dryer-Safety',array['laundry']::text[],'role','easy',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','Why shouldn''t you leave hot, just-dried towels piled in a cart overnight?','¿Por qué no se deben dejar toallas recién secadas y calientes amontonadas en un carrito toda la noche?','["They get too soft", "Guests prefer cold towels", "Oily residue in hot linens can self-heat and catch fire", "They change color"]'::jsonb,'["Se ponen demasiado suaves", "Los huéspedes prefieren toallas frías", "Los residuos de aceite en ropa caliente pueden calentarse solos y prenderse", "Cambian de color"]'::jsonb,2,'Let the cool-down cycle finish and spread hot linens out — spontaneous combustion is real in laundries.','Deja que termine el ciclo de enfriado y extiende la ropa caliente; en lavanderías la combustión espontánea sí pasa.','https://www.cpsc.gov/Safety-Education/Safety-Education-Centers/Clothes-Dryer-Safety',array['laundry']::text[],'role','hard',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stains','A white towel has makeup stains. What''s the right move?','Una toalla blanca tiene manchas de maquillaje. ¿Qué es lo correcto?','["Fold it and send it up", "Throw it away immediately", "Bleach it in the sink", "Pre-treat it per the stain process, then rewash"]'::jsonb,'["Doblarla y mandarla a los cuartos", "Tirarla de inmediato", "Echarle cloro en el lavabo", "Pretratarla según el proceso de manchas y volver a lavar"]'::jsonb,3,'Stained linen sent to rooms is a top guest complaint. Pre-treat and rewash; retire it if it won''t come out.','La ropa manchada en los cuartos es de las quejas más comunes. Pretrata y relava; si no sale, dala de baja.','general hospitality best practice',array['laundry']::text[],'role','med',array['stains','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stains','A sheet still has a stain after rewash. What do you do with it?','Una sábana sigue manchada después de relavarla. ¿Qué haces con ella?','["Send it up anyway", "Iron over it", "Pull it as a rag or reject per policy", "Put it on a bed with the stain at the bottom"]'::jsonb,'["Mandarla de todos modos", "Plancharla encima", "Retirarla como trapo o desecho según la política", "Ponerla en la cama con la mancha abajo"]'::jsonb,2,'Track rejects so the hotel can order replacements.','Lleva registro de lo que se da de baja para que el hotel pida reemplazos.','general hospitality best practice',array['laundry']::text[],'role','easy',array['stains','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sorting','Why sort linens before washing?','¿Por qué se separa la ropa antes de lavarla?','["To count them faster only", "Because machines only take one color", "Different items and soil levels need different wash formulas", "It doesn''t matter"]'::jsonb,'["Solo para contar más rápido", "Porque las máquinas solo aceptan un color", "Cada tipo de prenda y nivel de suciedad necesita una fórmula distinta", "No importa"]'::jsonb,2,'Sheets, towels, and heavily soiled rags each wash better on their own cycle.','Sábanas, toallas y trapos muy sucios se lavan mejor cada uno en su ciclo.','general hospitality best practice',array['laundry']::text[],'role','easy',array['sorting','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','blood','A bag of linen is marked as having blood on it. How should you handle it?','Una bolsa de ropa viene marcada con sangre. ¿Cómo la manejas?','["Leave it on the floor", "Shake it to check", "Wear gloves and follow the soiled-linen procedure; don''t shake it out", "Sort it bare-handed"]'::jsonb,'["Dejarla en el piso", "Sacudirla para revisar", "Usar guantes y seguir el procedimiento de ropa contaminada; no sacudirla", "Separarla sin guantes"]'::jsonb,2,'Shaking contaminated linen can spread fluids. Gloves on, minimal handling.','Sacudir ropa contaminada puede esparcir fluidos. Guantes puestos y manipularla lo menos posible.','https://www.osha.gov/bloodborne-pathogens',array['laundry']::text[],'role','med',array['blood','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sharps','You feel something sharp while sorting a linen bag. What do you do?','Sientes algo punzante al separar una bolsa de ropa. ¿Qué haces?','["Stop, don''t reach in, and get your supervisor", "Ignore it", "Dig around to find it", "Dump it on the table"]'::jsonb,'["Detenerte, no meter la mano y llamar a tu supervisora", "Ignorarlo", "Buscar con la mano", "Vaciarla en la mesa"]'::jsonb,0,'Needles and glass hide in linens. Never reach blindly into bags.','Agujas y vidrios se esconden en la ropa. Nunca metas la mano a ciegas.','https://www.osha.gov/bloodborne-pathogens',array['laundry']::text[],'role','med',array['sharps','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','machine','The washer door won''t open and the drum is still moving. What do you do?','La puerta de la lavadora no abre y el tambor sigue girando. ¿Qué haces?','["Hit the door", "Pry it open", "Wait for it to stop completely — never force the door", "Unplug and yank it"]'::jsonb,'["Golpear la puerta", "Abrirla con palanca", "Esperar a que pare por completo; nunca forzar la puerta", "Desconectarla y jalar"]'::jsonb,2,'Door locks protect you from a spinning drum. Report a stuck lock to maintenance.','El seguro de la puerta te protege del tambor girando. Reporta a mantenimiento si se atora.','general hospitality best practice',array['laundry']::text[],'role','med',array['machine','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','machine','A washer is leaking water onto the floor. First steps?','Una lavadora tira agua al piso. ¿Qué haces primero?','["Stand in the water to fix it", "Keep running loads", "Stop the machine, put up a wet-floor sign, and call maintenance", "Mop around it and leave"]'::jsonb,'["Pararte en el agua para arreglarla", "Seguir lavando", "Detener la máquina, poner letrero de piso mojado y llamar a mantenimiento", "Trapear alrededor y irte"]'::jsonb,2,'Water plus electric machines is dangerous. Stop it and keep people from slipping.','El agua y las máquinas eléctricas son peligrosas. Detén la máquina y evita resbalones.','https://www.osha.gov/walking-working-surfaces',array['laundry']::text[],'role','med',array['machine','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','Where do you find what to do if detergent gets on your skin?','¿Dónde encuentras qué hacer si el detergente te cae en la piel?','["The washer manual", "The product''s Safety Data Sheet (SDS)", "The schedule board", "The guest directory"]'::jsonb,'["El manual de la lavadora", "La hoja de datos de seguridad (SDS) del producto", "El tablero de horarios", "El directorio del huésped"]'::jsonb,1,'SDS sheets list first aid and required PPE. Know where the binder is.','Las SDS dicen los primeros auxilios y el equipo de protección. Sabe dónde está la carpeta.','https://www.osha.gov/hazcom',array['laundry']::text[],'role','med',array['chemicals','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ppe','What protective gear do you wear when changing chemical drums?','¿Qué equipo de protección usas al cambiar tambos de químicos?','["Sunglasses only", "Gloves and eye protection per the SDS", "Just your uniform", "Nothing if you''re quick"]'::jsonb,'["Solo lentes de sol", "Guantes y lentes de protección según la SDS", "Solo tu uniforme", "Nada si lo haces rápido"]'::jsonb,1,'Concentrated laundry chemicals can burn skin and eyes.','Los químicos de lavandería concentrados pueden quemar piel y ojos.','https://www.osha.gov/hazcom',array['laundry']::text[],'role','easy',array['ppe','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','folding','Why fold towels to the hotel''s standard every time?','¿Por qué doblar las toallas siempre según el estándar del hotel?','["Guests never notice", "So they dry", "Rooms look consistent and stacks fit carts and shelves", "It''s faster to skip it"]'::jsonb,'["Los huéspedes nunca lo notan", "Para que se sequen", "Los cuartos se ven iguales y las pilas caben en carritos y anaqueles", "Es más rápido no hacerlo"]'::jsonb,2,'Consistent folds make rooms look cared for and speed up attendants.','Los dobleces iguales hacen que los cuartos se vean cuidados y agilizan a las recamaristas.','general hospitality best practice',array['laundry']::text[],'role','easy',array['folding','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','par','Linen is running low at 10 a.m. on a full house. What should you tell your supervisor?','Falta ropa a las 10 a.m. con el hotel lleno. ¿Qué le avisas a tu supervisora?','["To close rooms", "That attendants should reuse sheets", "What''s short and how long until the next loads are ready", "Nothing, they''ll find out"]'::jsonb,'["Que cierren cuartos", "Que las recamaristas reusen sábanas", "Qué falta y en cuánto tiempo salen las siguientes cargas", "Nada, ya se darán cuenta"]'::jsonb,2,'Early heads-up lets the supervisor reorder rooms so no one waits.','Avisar temprano deja que la supervisora reorganice cuartos para que nadie espere.','general hospitality best practice',array['laundry']::text[],'role','med',array['par','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','How should you unload heavy wet sheets from a washer?','¿Cómo debes sacar sábanas mojadas y pesadas de la lavadora?','["Yank the whole load at once", "Pull smaller bundles into a cart at waist height", "Lean in and twist", "Use your foot"]'::jsonb,'["Jalar toda la carga de un golpe", "Sacar bultos pequeños a un carrito a la altura de la cintura", "Meterte y girar", "Usar el pie"]'::jsonb,1,'Wet linen is heavy. Smaller pulls without twisting protect your back.','La ropa mojada pesa. Sacarla de a poco y sin girar protege tu espalda.','https://www.osha.gov/ergonomics',array['laundry']::text[],'role','med',array['ergonomics','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','heat','The laundry room is very hot in July. What helps you stay safe?','La lavandería está muy caliente en julio. ¿Qué te ayuda a estar segura?','["Wear extra layers", "Drink water often, take cool breaks, and tell your supervisor if you feel dizzy", "Skip water to avoid bathroom breaks", "Work faster to finish"]'::jsonb,'["Ponerte más ropa", "Tomar agua seguido, descansar en un lugar fresco y avisar si te mareas", "No tomar agua para no ir al baño", "Trabajar más rápido para acabar"]'::jsonb,1,'Heat illness can come on fast near dryers. Water, rest and shade.','El golpe de calor puede llegar rápido cerca de las secadoras. Agua, descanso y sombra.','https://www.osha.gov/heat-exposure',array['laundry']::text[],'role','med',array['heat','laundry']::text[],null,'06-01','09-15',null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lostfound','You find a phone in a pillowcase. What do you do?','Encuentras un celular dentro de una funda. ¿Qué haces?','["Give it to the next guest", "Keep it in your locker", "Put it on the dryer", "Turn it in to lost and found with where and when it was found"]'::jsonb,'["Dárselo al siguiente huésped", "Guardarlo en tu locker", "Ponerlo sobre la secadora", "Entregarlo a objetos perdidos con dónde y cuándo se encontró"]'::jsonb,3,'Check pockets and pillowcases — and log every item found.','Revisa bolsillos y fundas, y registra todo lo que encuentres.','general hospitality best practice',array['laundry']::text[],'role','easy',array['lostfound','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','machine','Why not overload a washer?','¿Por qué no se debe sobrecargar una lavadora?','["Linens don''t get clean and the machine wears out faster", "It makes towels fluffier", "It''s what the manual says to do", "It saves water"]'::jsonb,'["La ropa no queda limpia y la máquina se desgasta más rápido", "Deja las toallas más esponjosas", "Así lo dice el manual", "Ahorra agua"]'::jsonb,0,'Clothes need room to move. Follow the machine''s weight rating.','La ropa necesita espacio para moverse. Respeta la capacidad de la máquina.','general hospitality best practice',array['laundry']::text[],'role','hard',array['machine','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','Where should clean linen never be placed?','¿Dónde nunca se debe poner la ropa limpia?','["On a clean shelf", "In a covered cart", "On a folding table", "On the floor or in carts used for dirty linen"]'::jsonb,'["En un anaquel limpio", "En un carrito tapado", "En una mesa de doblar", "En el piso o en carritos de ropa sucia"]'::jsonb,3,'Keep clean and dirty separate so clean linen stays clean.','Mantén lo limpio separado de lo sucio para que la ropa limpia siga limpia.','general hospitality best practice',array['laundry']::text[],'role','med',array['cleaning','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','bedbugs','Linen from a suspected bed bug room arrives sealed in a bag. How is it handled?','Llega ropa sellada en bolsa de un cuarto con posibles chinches. ¿Cómo se maneja?','["Keep it sealed until it goes straight into a hot wash and hot dryer", "Leave it in the hall", "Mix it with other linen", "Open it on the sorting table"]'::jsonb,'["Mantenerla sellada hasta meterla directo a lavado y secado caliente", "Dejarla en el pasillo", "Mezclarla con otra ropa", "Abrirla en la mesa de separar"]'::jsonb,0,'High heat kills bed bugs; opening the bag lets them escape.','El calor alto mata las chinches; abrir la bolsa las deja escapar.','https://www.cdc.gov/bed-bugs/about/index.html',array['laundry']::text[],'role','hard',array['bedbugs','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','You mopped the lobby floor. What must go out before you walk away?','Trapeaste el piso del lobby. ¿Qué debes poner antes de irte?','["Nothing", "A trash can", "A wet-floor sign", "A luggage cart"]'::jsonb,'["Nada", "Un bote de basura", "Un letrero de piso mojado", "Un carrito de maletas"]'::jsonb,2,'Wet floors are a top cause of guest and staff falls.','Los pisos mojados son de las principales causas de caídas.','https://www.osha.gov/walking-working-surfaces',array['houseman']::text[],'role','easy',array['safety','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safety','When is the best time to mop the lobby?','¿Cuál es el mejor momento para trapear el lobby?','["During morning checkout rush", "All at once at peak hours", "Only when a guest complains", "During slow times, one section at a time, with signs"]'::jsonb,'["Durante las salidas de la mañana", "Todo de una vez en hora pico", "Solo cuando se queja un huésped", "En horas tranquilas, por secciones y con letreros"]'::jsonb,3,'Working in sections leaves a dry path for guests.','Trabajar por secciones deja un camino seco para los huéspedes.','https://www.osha.gov/walking-working-surfaces',array['houseman']::text[],'role','med',array['safety','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','Snow is being tracked in at the entrance. What helps most?','Están metiendo nieve en la entrada. ¿Qué ayuda más?','["Spread towels from the rooms", "Put down absorbent mats and dry the area often", "Leave it to melt", "Open the doors wider"]'::jsonb,'["Poner toallas de los cuartos", "Poner tapetes absorbentes y secar seguido", "Dejar que se derrita", "Abrir más las puertas"]'::jsonb,1,'Entry mats and frequent drying prevent winter slip-and-falls.','Los tapetes de entrada y secar seguido evitan caídas en invierno.','https://www.osha.gov/winter-weather',array['houseman']::text[],'role','easy',array['winter','houseman']::text[],null,'11-01','04-01',null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','The sidewalk by the door is icy at 6 a.m. What should you do?','La banqueta junto a la puerta está congelada a las 6 a.m. ¿Qué haces?','["Put a chair there", "Wait for the sun", "Apply ice melt per instructions and tell the front desk", "Pour hot water on it"]'::jsonb,'["Poner una silla", "Esperar al sol", "Echar sal o derretidor según instrucciones y avisar a recepción", "Echarle agua caliente"]'::jsonb,2,'Hot water refreezes into more ice. Use ice melt and warn the desk.','El agua caliente se vuelve a congelar. Usa derretidor y avisa a recepción.','https://www.osha.gov/winter-weather',array['houseman']::text[],'role','med',array['winter','houseman']::text[],null,'11-01','04-01',null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','You''re refilling a spray bottle from a larger jug. What must the bottle have?','Estás rellenando una botella desde un galón. ¿Qué debe tener la botella?','["A label naming the chemical and its hazards", "Nothing, you''ll remember", "Your initials only", "A guest''s room number"]'::jsonb,'["Una etiqueta con el nombre del químico y sus riesgos", "Nada, ya te vas a acordar", "Solo tus iniciales", "El número de un cuarto"]'::jsonb,0,'Secondary containers must be labeled so anyone who picks it up knows what it is.','Los envases secundarios deben estar etiquetados para que cualquiera sepa qué contienen.','https://www.osha.gov/hazcom',array['houseman']::text[],'role','med',array['chemicals','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trash','A trash bag feels heavy and sharp items poke through. How do you carry it?','Una bolsa de basura pesa y se asoman cosas filosas. ¿Cómo la cargas?','["Swing it over your shoulder", "Drag it on the floor", "Hug it close", "Away from your body, not against your legs; double-bag if needed"]'::jsonb,'["Echártela al hombro", "Arrastrarla por el piso", "Abrazarla", "Lejos del cuerpo, no pegada a las piernas; usa doble bolsa si hace falta"]'::jsonb,3,'Broken glass and needles in trash cause cuts. Keep bags off your body.','Los vidrios y agujas en la basura causan cortadas. Mantén las bolsas lejos del cuerpo.','https://www.osha.gov/bloodborne-pathogens',array['houseman']::text[],'role','med',array['trash','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trash','Where should trash and dirty linen carts never be left?','¿Dónde nunca deben quedarse los carritos de basura o ropa sucia?','["Blocking hallways, exits or fire doors", "In the back hall", "In the service elevator area when moving", "In the trash room"]'::jsonb,'["Bloqueando pasillos, salidas o puertas contra incendio", "En el pasillo de servicio", "Junto al elevador de servicio cuando los mueves", "En el cuarto de basura"]'::jsonb,0,'Exits and fire doors must stay clear at all times.','Las salidas y puertas contra incendio deben estar libres siempre.','https://www.osha.gov/exit-routes',array['houseman']::text[],'role','easy',array['trash','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','public','What areas should you check on every public-area round?','¿Qué áreas debes revisar en cada ronda de áreas públicas?','["Lobby restrooms, entrance, elevators and ice/vending areas", "Guest rooms", "The roof", "Only the GM''s office"]'::jsonb,'["Baños del lobby, entrada, elevadores y áreas de hielo y máquinas", "Los cuartos", "El techo", "Solo la oficina del gerente"]'::jsonb,0,'Public spaces shape first impressions. Regular rounds keep them guest-ready.','Las áreas públicas dan la primera impresión. Las rondas las mantienen listas.','general hospitality best practice',array['houseman']::text[],'role','easy',array['public','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','public','A guest gets sick in the elevator. What do you do first?','Un huésped vomita en el elevador. ¿Qué haces primero?','["Leave it for night shift", "Take that elevator out of service, put on gloves, and clean with the body-fluid kit", "Spray air freshener only", "Wipe it with a dry rag"]'::jsonb,'["Dejárselo al turno de noche", "Sacar ese elevador de servicio, ponerte guantes y limpiar con el kit de fluidos", "Solo echar aromatizante", "Limpiarlo con un trapo seco"]'::jsonb,1,'Body fluids need PPE and a disinfectant made for them.','Los fluidos corporales requieren equipo de protección y un desinfectante adecuado.','https://www.osha.gov/bloodborne-pathogens',array['houseman']::text[],'role','med',array['public','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','You need to move a heavy furniture piece alone. What''s best?','Necesitas mover un mueble pesado tú solo. ¿Qué es lo mejor?','["Ask a guest", "Drag it across carpet with your back", "Lift fast to get it over with", "Get a coworker or a dolly — don''t lift it alone"]'::jsonb,'["Pedirle a un huésped", "Arrastrarlo con la espalda", "Levantarlo rápido para acabar", "Pedir ayuda a un compañero o usar un diablito; no lo levantes solo"]'::jsonb,3,'Team lifts and carts prevent back injuries.','Levantar en equipo o con carrito evita lesiones de espalda.','https://www.osha.gov/ergonomics',array['houseman']::text[],'role','med',array['ergonomics','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ladder','You need to dust a high light fixture. What''s safe?','Tienes que sacudir una lámpara alta. ¿Qué es lo seguro?','["Use a proper ladder or extension duster, not a chair", "Climb on the luggage cart", "Stand on the top step of the ladder", "Stand on a desk chair with wheels"]'::jsonb,'["Usar una escalera adecuada o un plumero extensible, no una silla", "Subirte al carrito de maletas", "Pararte en el último escalón", "Pararte en una silla con ruedas"]'::jsonb,0,'Chairs and carts roll. Use the right ladder and never the top step.','Las sillas y carritos ruedan. Usa la escalera correcta y nunca el último escalón.','https://www.osha.gov/ladders',array['houseman']::text[],'role','med',array['ladder','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','guest','A guest asks where the ice machine is while you''re vacuuming. What do you do?','Un huésped te pregunta dónde está la máquina de hielo mientras aspiras. ¿Qué haces?','["Say you don''t know", "Keep vacuuming and point", "Turn off the vacuum, smile, and give clear directions", "Tell them to ask the desk"]'::jsonb,'["Decir que no sabes", "Seguir aspirando y señalar", "Apagar la aspiradora, sonreír y explicar bien", "Mandarlo a recepción"]'::jsonb,2,'Stopping to help shows guests they matter.','Detenerte a ayudar le demuestra al huésped que importa.','general hospitality best practice',array['houseman']::text[],'role','easy',array['guest','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','You notice the pool water is cloudy and you can''t see the bottom. What should happen?','Notas que el agua de la alberca está turbia y no se ve el fondo. ¿Qué debe pasar?','["Ignore it", "Report it right away — the pool may need to close until it''s clear", "Swim to check", "Add bleach from housekeeping"]'::jsonb,'["Ignorarlo", "Reportarlo de inmediato; quizá se deba cerrar hasta que se aclare", "Nadar para revisar", "Echarle cloro de limpieza"]'::jsonb,1,'Minnesota requires the main drain to be visible; cloudy water is a safety hazard.','En Minnesota se debe ver el desagüe del fondo; el agua turbia es un riesgo.','https://www.health.state.mn.us/communities/environment/pools/index.html',array['houseman']::text[],'role','med',array['pool','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','public','Restroom paper towels are out during a busy event. What''s the priority?','Se acabaron las toallas de papel del baño durante un evento. ¿Qué es lo prioritario?','["Wait for the next round", "Tell guests to use the room", "Restock right away and add more frequent checks", "Leave a note"]'::jsonb,'["Esperar a la siguiente ronda", "Decirle a los huéspedes que usen su cuarto", "Reponer de inmediato y revisar más seguido", "Dejar una nota"]'::jsonb,2,'Busy times need more frequent rounds.','En horas de mucha gente hay que hacer más rondas.','general hospitality best practice',array['houseman']::text[],'role','med',array['public','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','You see a door to the back hallway propped open with a wedge. What do you do?','Ves una puerta del pasillo de servicio detenida con una cuña. ¿Qué haces?','["Lock yourself out", "Remove the wedge, close it, and tell your supervisor", "Leave it for airflow", "Prop more doors"]'::jsonb,'["Quedarte afuera", "Quitar la cuña, cerrarla y avisar a tu supervisora", "Dejarla para que entre aire", "Abrir más puertas"]'::jsonb,1,'Propped doors let anyone in and defeat fire doors.','Las puertas detenidas dejan entrar a cualquiera y anulan las puertas contra incendio.','general hospitality best practice',array['houseman']::text[],'role','med',array['security','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','The vacuum cord is frayed with wire showing. What do you do?','El cable de la aspiradora está pelado y se ve el alambre. ¿Qué haces?','["Use it only on carpet", "Tape it and keep going", "Stop using it, tag it out and report it", "Wrap it in a towel"]'::jsonb,'["Usarla solo en alfombra", "Ponerle cinta y seguir", "Dejar de usarla, marcarla fuera de servicio y reportarla", "Envolverla en una toalla"]'::jsonb,2,'Damaged cords can shock or start fires.','Los cables dañados pueden dar toques o causar incendios.','https://www.osha.gov/electrical',array['houseman']::text[],'role','med',array['electrical','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','shampoo','After shampooing carpet in the hallway, what should you do?','Después de lavar la alfombra del pasillo, ¿qué debes hacer?','["Lay towels on top", "Put up signs and use fans so it dries quickly", "Close the hallway for a week", "Leave it soaked"]'::jsonb,'["Poner toallas encima", "Poner letreros y ventiladores para que seque rápido", "Cerrar el pasillo una semana", "Dejarla empapada"]'::jsonb,1,'Damp carpet is slippery and can grow mildew.','La alfombra húmeda resbala y puede hacer moho.','https://www.osha.gov/walking-working-surfaces',array['houseman']::text[],'role','med',array['shampoo','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trash','Why keep the trash room or dumpster area tidy and closed?','¿Por qué mantener limpio y cerrado el cuarto de basura o el contenedor?','["Guests like to see it", "It keeps pests and smells away", "So the truck skips it", "It''s only for looks"]'::jsonb,'["A los huéspedes les gusta verlo", "Mantiene lejos plagas y olores", "Para que el camión no pase", "Solo es por apariencia"]'::jsonb,1,'Open dumpsters attract rodents and insects.','Los contenedores abiertos atraen ratas e insectos.','general hospitality best practice',array['houseman']::text[],'role','med',array['trash','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','guest','A guest in the lobby looks lost and upset. What should you do?','Un huésped en el lobby se ve perdido y molesto. ¿Qué haces?','["Keep cleaning", "Tell them to calm down", "Ask if you can help and walk them to the front desk if needed", "Look away"]'::jsonb,'["Seguir limpiando", "Decirle que se calme", "Preguntarle si le puedes ayudar y llevarlo a recepción si hace falta", "Voltear para otro lado"]'::jsonb,2,'Every staff member can be the one who turns a bad moment around.','Cualquiera del equipo puede cambiar un mal momento.','general hospitality best practice',array['houseman']::text[],'role','med',array['guest','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ice','Why shouldn''t the ice scoop be stored inside the ice bin?','¿Por qué no se debe guardar la pala del hielo dentro del depósito?','["It''s too heavy", "It makes noise", "It melts the ice", "Hands touch the handle and can contaminate the ice"]'::jsonb,'["Pesa mucho", "Hace ruido", "Derrite el hielo", "Las manos tocan el mango y pueden contaminar el hielo"]'::jsonb,3,'Ice is food. Keep the scoop in its holder.','El hielo es alimento. Guarda la pala en su soporte.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['houseman']::text[],'role','med',array['ice','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','loto','Before working on a PTAC unit''s wiring, what must you do?','Antes de trabajar en el cableado de un PTAC, ¿qué debes hacer?','["Work fast", "Just turn it off at the remote", "Unplug it halfway", "Shut off and lock out the power, then verify it''s dead"]'::jsonb,'["Trabajar rápido", "Solo apagarlo con el control", "Desconectarlo a medias", "Cortar y bloquear la energía, y comprobar que no haya corriente"]'::jsonb,3,'Lockout/tagout prevents someone from turning power back on while you work.','El bloqueo y etiquetado evita que alguien vuelva a dar energía mientras trabajas.','https://www.osha.gov/control-hazardous-energy',array['maintenance']::text[],'role','med',array['loto','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','loto','After locking out a breaker, what''s the next step before touching wires?','Después de bloquear un breaker, ¿qué sigue antes de tocar los cables?','["Test with a meter to confirm there''s no voltage", "Assume it''s off", "Touch the wire quickly to check", "Remove the lock"]'::jsonb,'["Probar con un multímetro que no haya voltaje", "Suponer que ya está apagado", "Tocar el cable rápido para ver", "Quitar el candado"]'::jsonb,0,'Verify zero energy — breakers can be mislabeled.','Comprueba que no haya energía; los breakers pueden estar mal rotulados.','https://www.osha.gov/control-hazardous-energy',array['maintenance']::text[],'role','hard',array['loto','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','loto','Who removes a lockout lock?','¿Quién quita un candado de bloqueo?','["Whoever needs the equipment", "The front desk", "Only the person who put it on", "Any manager without checking"]'::jsonb,'["Quien necesite el equipo", "La recepción", "Solo la persona que lo puso", "Cualquier gerente sin revisar"]'::jsonb,2,'Your lock, your key — that''s what keeps you safe.','Tu candado, tu llave; así te mantienes seguro.','https://www.osha.gov/control-hazardous-energy',array['maintenance']::text[],'role','med',array['loto','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ladder','An extension ladder should extend how far above the roof edge you step onto?','¿Cuánto debe sobresalir una escalera de extensión del borde del techo al que te subes?','["At least 3 feet", "10 feet", "It shouldn''t extend past it", "6 inches"]'::jsonb,'["Al menos 3 pies", "10 pies", "No debe sobresalir", "6 pulgadas"]'::jsonb,0,'OSHA requires side rails to extend at least 3 feet above the landing.','OSHA exige que los rieles sobresalgan al menos 3 pies del punto de apoyo.','https://www.osha.gov/ladders',array['maintenance']::text[],'role','med',array['ladder','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ladder','A stepladder''s top cap says ''Do not stand.'' Why?','La tapa de una escalera de tijera dice ''No pararse aquí''. ¿Por qué?','["It''s for paint cans only", "You can lose balance and tip it over", "It''s only a sticker", "It''s fine for quick jobs"]'::jsonb,'["Es solo para botes de pintura", "Puedes perder el equilibrio y voltearla", "Es solo una calcomanía", "Está bien para trabajos rápidos"]'::jsonb,1,'Use a taller ladder instead of the top cap.','Usa una escalera más alta en lugar de pararte en la tapa.','https://www.osha.gov/ladders',array['maintenance']::text[],'role','easy',array['ladder','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','A GFCI outlet in a bathroom won''t reset. What does that tell you?','Un contacto GFCI del baño no se restablece. ¿Qué te indica?','["Tape the button down", "There may be a ground fault or bad outlet — investigate before using it", "Nothing, use another plug", "It needs a bigger fuse"]'::jsonb,'["Pegarle cinta al botón", "Puede haber falla a tierra o el contacto está dañado; revisa antes de usarlo", "Nada, usa otro contacto", "Necesita un fusible más grande"]'::jsonb,1,'GFCIs trip to prevent shock near water.','Los GFCI se botan para evitar descargas cerca del agua.','https://www.osha.gov/electrical',array['maintenance']::text[],'role','med',array['electrical','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','electrical','Why are GFCI outlets required near sinks and tubs?','¿Por qué se requieren contactos GFCI cerca de lavabos y tinas?','["They charge phones faster", "They look nicer", "They save electricity", "They cut power fast to prevent shock near water"]'::jsonb,'["Cargan más rápido los celulares", "Se ven mejor", "Ahorran electricidad", "Cortan la corriente rápido para evitar descargas cerca del agua"]'::jsonb,3,'Water and electricity are a deadly mix; GFCIs react in milliseconds.','El agua y la electricidad son peligrosas; los GFCI reaccionan en milisegundos.','https://www.osha.gov/electrical',array['maintenance']::text[],'role','easy',array['electrical','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','legionella','Why flush water in guest rooms that haven''t been used for a while?','¿Por qué dejar correr el agua en cuartos que no se han usado en un tiempo?','["To clean the tub", "Stagnant water can grow Legionella bacteria", "It''s not needed", "To test water pressure only"]'::jsonb,'["Para limpiar la tina", "El agua estancada puede generar la bacteria Legionella", "No hace falta", "Solo para probar la presión"]'::jsonb,1,'Legionella grows in still, lukewarm water and spreads through showerhead mist.','La Legionella crece en agua quieta y tibia y se transmite por el vapor de la regadera.','https://www.cdc.gov/control-legionella/php/toolkit/',array['maintenance']::text[],'role','hard',array['legionella','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','legionella','What hot-water practice helps control Legionella?','¿Qué práctica de agua caliente ayuda a controlar la Legionella?','["Keep the water heater hot enough per the water management plan and avoid stagnant lines", "Turn it off at night", "Only use cold water", "Set it as low as possible"]'::jsonb,'["Mantener el calentador lo bastante caliente según el plan de manejo de agua y evitar líneas estancadas", "Apagarlo de noche", "Usar solo agua fría", "Ponerlo lo más bajo posible"]'::jsonb,0,'Lukewarm water is the danger zone. Follow the hotel''s water management plan.','El agua tibia es la zona de riesgo. Sigue el plan de manejo de agua del hotel.','https://www.cdc.gov/control-legionella/php/toolkit/',array['maintenance']::text[],'role','hard',array['legionella','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','co','A guest reports a headache and the CO alarm chirps near the boiler room. What do you do?','Un huésped reporta dolor de cabeza y la alarma de CO suena cerca del cuarto de calderas. ¿Qué haces?','["Open a window and stay", "Wait for it to stop", "Get people out to fresh air, call 911, and don''t re-enter", "Silence the alarm and keep working"]'::jsonb,'["Abrir una ventana y quedarte", "Esperar a que pare", "Sacar a la gente al aire libre, llamar al 911 y no volver a entrar", "Silenciar la alarma y seguir"]'::jsonb,2,'Carbon monoxide is invisible and odorless. Evacuate and call for help.','El monóxido de carbono no se ve ni se huele. Evacua y pide ayuda.','https://www.epa.gov/indoor-air-quality-iaq/carbon-monoxides-impact-indoor-air-quality',array['maintenance']::text[],'role','med',array['co','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','co','Which equipment can produce carbon monoxide in a hotel?','¿Qué equipo puede producir monóxido de carbono en un hotel?','["Ice machines", "LED lights", "Gas boilers, water heaters and dryers", "TVs"]'::jsonb,'["Máquinas de hielo", "Focos LED", "Calderas, calentadores y secadoras de gas", "Televisiones"]'::jsonb,2,'Anything that burns fuel can make CO if it''s not venting right.','Todo lo que quema combustible puede generar CO si no ventila bien.','https://www.epa.gov/indoor-air-quality-iaq/carbon-monoxides-impact-indoor-air-quality',array['maintenance']::text[],'role','easy',array['co','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','What does PASS stand for when using a fire extinguisher?','¿Qué significa PASS al usar un extintor?','["Point, Ask, Shoot, Stand", "Push, Alarm, Spray, Stop", "Pull, Aim, Squeeze, Sweep", "Pull, Alert, Spray, Shut"]'::jsonb,'["Señalar, Preguntar, Disparar, Pararse", "Empujar, Alarma, Rociar, Parar", "Jalar, Apuntar, Apretar, Barrer", "Jalar, Alertar, Rociar, Cerrar"]'::jsonb,2,'Aim at the base of the fire and sweep side to side.','Apunta a la base del fuego y barre de lado a lado.','https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers',array['maintenance']::text[],'role','easy',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','How often should portable fire extinguishers get a quick visual check?','¿Cada cuánto se deben revisar a simple vista los extintores portátiles?','["Every 5 years only", "Only after a fire", "Never", "Monthly"]'::jsonb,'["Solo cada 5 años", "Solo después de un incendio", "Nunca", "Cada mes"]'::jsonb,3,'OSHA requires monthly visual inspections and annual maintenance.','OSHA pide revisión visual mensual y mantenimiento anual.','https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers',array['maintenance']::text[],'role','med',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','A sprinkler head in a room is painted over. What should happen?','Un rociador de un cuarto está pintado. ¿Qué debe pasar?','["Scrape the paint off with a knife", "Report it — it may need replacing by a licensed contractor", "Hang a hanger on it", "Leave it"]'::jsonb,'["Rasparle la pintura con un cuchillo", "Reportarlo; puede necesitar reemplazo por un contratista certificado", "Colgarle un gancho", "Dejarlo así"]'::jsonb,1,'Paint can stop a sprinkler from opening in a fire.','La pintura puede impedir que el rociador funcione en un incendio.','https://www.nfpa.org/codes-and-standards/nfpa-25-standard-development/25',array['maintenance']::text[],'role','med',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','Who should adjust pool chemicals?','¿Quién debe ajustar los químicos de la alberca?','["Housekeeping", "Guests", "Only trained staff following the hotel''s pool procedure and MN rules", "Anyone with a bucket"]'::jsonb,'["Limpieza", "Los huéspedes", "Solo personal capacitado siguiendo el procedimiento del hotel y las reglas de MN", "Cualquiera con una cubeta"]'::jsonb,2,'Pool chemicals are dangerous and regulated by the MN Department of Health.','Los químicos de alberca son peligrosos y los regula el Departamento de Salud de MN.','https://www.health.state.mn.us/communities/environment/pools/index.html',array['maintenance']::text[],'role','med',array['pool','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','Why must pool chemicals like chlorine and acid be stored apart?','¿Por qué se guardan por separado químicos de alberca como cloro y ácido?','["They expire faster together", "Mixing them can release toxic chlorine gas", "To save space", "They look alike"]'::jsonb,'["Caducan más rápido juntos", "Al mezclarse pueden soltar gas de cloro tóxico", "Para ahorrar espacio", "Se parecen"]'::jsonb,1,'Store separately, labeled, and never add water to concentrated chemicals.','Guárdalos separados y etiquetados, y nunca les eches agua a los concentrados.','https://www.osha.gov/hazcom',array['maintenance']::text[],'role','hard',array['pool','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','What''s the main risk when the heat fails in a room during a Minnesota cold snap?','¿Cuál es el riesgo principal si falla la calefacción de un cuarto en una ola de frío en Minnesota?','["Nothing", "Louder TV", "Brighter lights", "Frozen and burst pipes, plus an unsafe room for guests"]'::jsonb,'["Nada", "Tele más fuerte", "Luces más brillantes", "Tuberías congeladas o reventadas, y un cuarto inseguro para el huésped"]'::jsonb,3,'Prioritize heat calls in winter and move guests if needed.','En invierno, prioriza las fallas de calefacción y cambia al huésped de cuarto si hace falta.','https://www.osha.gov/winter-weather',array['maintenance']::text[],'role','med',array['winter','maintenance']::text[],null,'11-15','03-15',null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','Before winter, what should you check on outdoor faucets?','Antes del invierno, ¿qué revisas en las llaves de agua exteriores?','["Shut off and drain them so they don''t freeze", "Paint them", "Leave hoses attached", "Turn them on full"]'::jsonb,'["Cerrarlas y drenarlas para que no se congelen", "Pintarlas", "Dejar las mangueras conectadas", "Abrirlas por completo"]'::jsonb,0,'Attached hoses trap water that freezes and cracks pipes.','Las mangueras conectadas atrapan agua que se congela y rompe tubos.','https://www.osha.gov/winter-weather',array['maintenance']::text[],'role','med',array['winter','maintenance']::text[],null,'09-15','11-30',null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','hvac','Why change PTAC and HVAC filters on schedule?','¿Por qué cambiar a tiempo los filtros de los PTAC y del HVAC?','["Filters never matter", "It''s only for looks", "It makes units louder", "Clean filters improve air, comfort and unit life"]'::jsonb,'["No importan", "Solo es por apariencia", "Hace más ruido el equipo", "Los filtros limpios mejoran el aire, la comodidad y la vida del equipo"]'::jsonb,3,'Dirty filters cause weak airflow, odors and breakdowns.','Los filtros sucios causan poco aire, olores y fallas.','general hospitality best practice',array['maintenance']::text[],'role','easy',array['hvac','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','hvac','A PTAC is dripping water inside the room. Most common cause?','Un PTAC gotea agua dentro del cuarto. ¿Cuál es la causa más común?','["The TV is too close", "A clogged condensate drain or unit not tilted to drain outside", "Too many towels", "The light is on"]'::jsonb,'["La tele está muy cerca", "Un drenaje de condensado tapado o el equipo no inclinado hacia afuera", "Demasiadas toallas", "La luz está prendida"]'::jsonb,1,'Clear the drain and check the unit''s pitch.','Destapa el drenaje y revisa la inclinación del equipo.','general hospitality best practice',array['maintenance']::text[],'role','med',array['hvac','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','plumbing','A toilet keeps running after flushing. What''s the likely fix?','Un inodoro sigue corriendo después de jalarle. ¿Qué es lo más probable?','["Ignore it", "Turn off the hotel''s water", "Adjust or replace the flapper or fill valve", "Replace the whole toilet"]'::jsonb,'["Ignorarlo", "Cortar el agua del hotel", "Ajustar o cambiar el sapo (flapper) o la válvula de llenado", "Cambiar todo el inodoro"]'::jsonb,2,'A running toilet wastes a lot of water and keeps guests up.','Un inodoro que corre desperdicia mucha agua y no deja dormir.','general hospitality best practice',array['maintenance']::text[],'role','easy',array['plumbing','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','plumbing','Water is leaking through a ceiling from the room above. What''s first?','Se está filtrando agua del techo desde el cuarto de arriba. ¿Qué es lo primero?','["Wait until checkout", "Paint the ceiling", "Find the source above and shut off that water, then protect the room below", "Put a bucket and leave"]'::jsonb,'["Esperar a la salida", "Pintar el techo", "Buscar el origen arriba y cerrar esa agua, luego proteger el cuarto de abajo", "Poner una cubeta e irte"]'::jsonb,2,'Stop the water first; then deal with damage and guests.','Primero corta el agua; después atiende los daños y a los huéspedes.','general hospitality best practice',array['maintenance']::text[],'role','med',array['plumbing','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','work_orders','Why log every repair in the work order system?','¿Por qué registrar cada reparación en el sistema de órdenes de trabajo?','["It''s just paperwork", "It tracks repeat problems, parts and rooms out of order", "It isn''t needed", "For the guest to see"]'::jsonb,'["Es solo papeleo", "Lleva el control de fallas repetidas, piezas y cuartos fuera de servicio", "No hace falta", "Para que lo vea el huésped"]'::jsonb,1,'Good records show what to fix for good and what to budget.','Un buen registro muestra qué arreglar de fondo y qué presupuestar.','general hospitality best practice',array['maintenance']::text[],'role','easy',array['work_orders','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','work_orders','Which work order do you do first?','¿Qué orden de trabajo atiendes primero?','["Changing a light in the office", "A squeaky door in storage", "Touch-up paint in a hallway", "Safety and guest-occupied problems, like no heat or a leak"]'::jsonb,'["Cambiar un foco en la oficina", "Una puerta que rechina en la bodega", "Retocar pintura en un pasillo", "Lo de seguridad y cuartos ocupados, como falta de calefacción o una fuga"]'::jsonb,3,'Safety first, then guests, then preventive work.','Primero seguridad, luego huéspedes, luego mantenimiento preventivo.','general hospitality best practice',array['maintenance']::text[],'role','med',array['work_orders','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','elevator','A guest is stuck in the elevator. What do you do?','Un huésped está atrapado en el elevador. ¿Qué haces?','["Pry open the doors", "Shut off the building power", "Tell them to climb out", "Talk to them to keep calm and call the elevator company or 911 — don''t force the doors"]'::jsonb,'["Abrir las puertas con palanca", "Cortar la luz del edificio", "Decirle que se salga trepando", "Hablarle para calmarlo y llamar a la compañía de elevadores o al 911; no forzar las puertas"]'::jsonb,3,'Only elevator technicians or firefighters should do rescues.','Solo técnicos de elevadores o bomberos deben hacer rescates.','general hospitality best practice',array['maintenance']::text[],'role','med',array['elevator','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ppe','When using a grinder or drill, what protects your eyes?','Al usar una esmeriladora o taladro, ¿qué protege tus ojos?','["Nothing if it''s quick", "Regular glasses only", "Squinting", "Safety glasses or goggles"]'::jsonb,'["Nada si es rápido", "Solo tus lentes normales", "Entrecerrar los ojos", "Lentes o gafas de seguridad"]'::jsonb,3,'Flying debris causes many workplace eye injuries.','Las partículas que salen volando causan muchas lesiones de ojos en el trabajo.','https://www.osha.gov/eye-face-protection',array['maintenance']::text[],'role','easy',array['ppe','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','You''re using a strong drain cleaner. Where''s the safest place to check its PPE needs?','Vas a usar un destapacaños fuerte. ¿Dónde revisas qué protección necesitas?','["The label and SDS", "Guess", "Online reviews", "Ask a guest"]'::jsonb,'["La etiqueta y la SDS", "Adivinar", "Reseñas en internet", "Preguntarle a un huésped"]'::jsonb,0,'Drain cleaners can cause serious burns. The SDS lists the PPE.','Los destapacaños pueden causar quemaduras graves. La SDS dice qué protección usar.','https://www.osha.gov/hazcom',array['maintenance']::text[],'role','med',array['chemicals','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','Why must a guest room lock be fixed the same day it''s reported?','¿Por qué se debe arreglar el mismo día una chapa de cuarto que se reporta?','["Guests don''t care", "An unsecured room is a safety risk and can''t be sold", "It can wait a week", "It only affects the look"]'::jsonb,'["A los huéspedes no les importa", "Un cuarto sin seguridad es un riesgo y no se puede vender", "Puede esperar una semana", "Solo afecta la apariencia"]'::jsonb,1,'Locks, deadbolts and door closers protect guests — top priority.','Las chapas, cerrojos y cierrapuertas protegen al huésped; son prioridad.','general hospitality best practice',array['maintenance']::text[],'role','med',array['security','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','Why must fire doors close and latch on their own?','¿Por qué las puertas contra incendio deben cerrar y trabarse solas?','["They slow smoke and fire from spreading", "For privacy", "To keep the hall quiet", "They don''t need to"]'::jsonb,'["Frenan el humo y el fuego para que no se extiendan", "Por privacidad", "Para que el pasillo esté callado", "No hace falta"]'::jsonb,0,'Report any fire door that doesn''t close fully.','Reporta cualquier puerta contra incendio que no cierre bien.','https://www.nfpa.org/codes-and-standards/nfpa-80-standard-development/80',array['maintenance']::text[],'role','hard',array['fire','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','Cold foods like yogurt and milk must be held at what temperature or below?','¿A qué temperatura o menos se deben mantener alimentos fríos como yogur y leche?','["60°F (16°C)", "50°F (10°C)", "41°F (5°C)", "32°F only"]'::jsonb,'["60°F (16°C)", "50°F (10°C)", "41°F (5°C)", "Solo 32°F"]'::jsonb,2,'The FDA Food Code sets cold holding at 41°F or below.','El Código de Alimentos de la FDA marca 41°F o menos para mantener en frío.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','Hot foods like eggs and sausage must be held at what temperature or above?','¿A qué temperatura o más se deben mantener alimentos calientes como huevo y salchicha?','["100°F (38°C)", "135°F (57°C)", "90°F (32°C)", "110°F (43°C)"]'::jsonb,'["100°F (38°C)", "135°F (57°C)", "90°F (32°C)", "110°F (43°C)"]'::jsonb,1,'Hot holding at 135°F or above keeps bacteria from growing.','Mantener a 135°F o más evita que crezcan bacterias.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','What''s the temperature ''danger zone'' where bacteria grow fastest?','¿Cuál es la ''zona de peligro'' de temperatura donde las bacterias crecen más rápido?','["Only at room temperature exactly", "Between 41°F and 135°F", "Below 32°F", "Above 200°F"]'::jsonb,'["Solo a temperatura ambiente exacta", "Entre 41°F y 135°F", "Abajo de 32°F", "Arriba de 200°F"]'::jsonb,1,'Keep cold food cold and hot food hot to stay out of the danger zone.','Mantén lo frío frío y lo caliente caliente para salir de la zona de peligro.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','Leftover sausage is being reheated for hot holding. To what temperature?','Se recalienta salchicha que sobró para mantenerla caliente. ¿A qué temperatura?','["135°F after 4 hours", "Just warm to the touch", "165°F (74°C) within 2 hours", "120°F"]'::jsonb,'["135°F después de 4 horas", "Solo tibia al tacto", "165°F (74°C) en menos de 2 horas", "120°F"]'::jsonb,2,'The Food Code requires reheating to 165°F within 2 hours for hot holding.','El Código pide recalentar a 165°F en menos de 2 horas para mantener caliente.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','How should you check the temperature of food on the buffet?','¿Cómo debes revisar la temperatura de la comida en el buffet?','["With a room thermostat", "By touching it", "With a clean, sanitized probe thermometer in the thickest part", "By looking at the steam"]'::jsonb,'["Con el termostato del cuarto", "Tocándola", "Con un termómetro de sonda limpio y desinfectado en la parte más gruesa", "Viendo el vapor"]'::jsonb,2,'Log temps on a schedule — steam doesn''t mean it''s hot enough.','Anota temperaturas en horario; el vapor no significa que esté bastante caliente.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','hard',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','temps','Cooked food must cool from 135°F to 70°F within how long?','La comida cocida debe enfriarse de 135°F a 70°F en cuánto tiempo?','["There is no time limit", "Half a day", "Within 2 hours", "By the next morning"]'::jsonb,'["No hay límite de tiempo", "En medio día", "En máximo 2 horas", "Para la mañana siguiente"]'::jsonb,2,'Then from 70°F to 41°F within 4 more hours.','Luego de 70°F a 41°F en máximo 4 horas más.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','hard',array['temps','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','handwash','How long should you scrub your hands when washing?','¿Cuánto tiempo debes tallarte las manos al lavártelas?','["Just a rinse", "1 minute of only water", "At least 20 seconds", "3 seconds"]'::jsonb,'["Solo enjuagarlas", "1 minuto solo con agua", "Al menos 20 segundos", "3 segundos"]'::jsonb,2,'Soap, 20 seconds of scrubbing, rinse, and dry with a paper towel.','Jabón, 20 segundos tallando, enjuagar y secar con toalla de papel.','https://www.cdc.gov/clean-hands/about/index.html',array['breakfast']::text[],'role','easy',array['handwash','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','handwash','When must you wash your hands during breakfast service?','¿Cuándo debes lavarte las manos durante el desayuno?','["Only after using the restroom", "Only at the start of shift", "After touching trash, your face, or raw eggs, and before putting on gloves", "Never if wearing gloves"]'::jsonb,'["Solo al ir al baño", "Solo al empezar el turno", "Después de tocar basura, tu cara o huevo crudo, y antes de ponerte guantes", "Nunca si usas guantes"]'::jsonb,2,'Gloves don''t replace handwashing.','Los guantes no sustituyen el lavado de manos.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['handwash','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','handwash','Where should you wash your hands in the breakfast area?','¿Dónde debes lavarte las manos en el área de desayuno?','["At the designated handwashing sink only", "In the food prep sink", "In the mop sink", "In the coffee station sink"]'::jsonb,'["Solo en el lavamanos designado", "En la tarja de preparar comida", "En la tarja de trapeador", "En la tarja de la estación de café"]'::jsonb,0,'Handwashing sinks are only for hands, so food sinks stay clean.','El lavamanos es solo para manos, para que las tarjas de comida sigan limpias.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['handwash','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','How many major food allergens does US law recognize?','¿Cuántos alérgenos principales reconoce la ley de EE. UU.?','["5", "9", "3", "12"]'::jsonb,'["5", "9", "3", "12"]'::jsonb,1,'Milk, eggs, fish, shellfish, tree nuts, peanuts, wheat, soy and sesame (added 2023).','Leche, huevo, pescado, mariscos, nueces, cacahuate, trigo, soya y ajonjolí (desde 2023).','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','med',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','A guest asks if the muffins contain nuts. You''re not sure. What do you say?','Un huésped pregunta si los muffins tienen nueces. No estás segura. ¿Qué dices?','["No, they''re fine", "Just pick around them", "Probably not", "I''ll check the package label for you"]'::jsonb,'["No, no tienen", "Nada más quíteles lo que no quiera", "Probablemente no", "Le reviso la etiqueta del paquete"]'::jsonb,3,'Never guess about allergens. Check the label or say you can''t confirm.','Nunca adivines con alérgenos. Revisa la etiqueta o di que no lo puedes confirmar.','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','med',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','allergens','Why use a separate tongs for each buffet item?','¿Por qué usar pinzas separadas para cada alimento del buffet?','["To look fancy", "Because tongs break", "So guests use more", "To prevent allergen cross-contact between foods"]'::jsonb,'["Para verse elegante", "Porque las pinzas se rompen", "Para que los huéspedes sirvan más", "Para evitar el contacto cruzado de alérgenos entre alimentos"]'::jsonb,3,'Sharing utensils can move nuts or wheat to an allergy-safe item.','Compartir utensilios puede pasar nueces o trigo a un alimento seguro.','https://www.fda.gov/food/food-labeling-nutrition/food-allergies',array['breakfast']::text[],'role','hard',array['allergens','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','eggs','Scrambled eggs cooked for immediate service must reach what internal temperature?','Los huevos revueltos para servir de inmediato deben llegar a qué temperatura interna?','["145°F (63°C) for 15 seconds", "100°F", "120°F", "165°F for 1 minute only"]'::jsonb,'["145°F (63°C) por 15 segundos", "100°F", "120°F", "165°F por solo 1 minuto"]'::jsonb,0,'Food Code: 145°F for eggs cooked to order; 155°F if held hot.','Código de Alimentos: 145°F para huevos al momento; 155°F si se mantienen calientes.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['eggs','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','eggs','Where should raw shell eggs be stored in the fridge?','¿Dónde se guardan los huevos crudos en el refrigerador?','["On the top shelf above fruit", "Next to the yogurt", "On a lower shelf, below ready-to-eat foods", "At room temperature"]'::jsonb,'["En el estante de arriba sobre la fruta", "Junto al yogur", "En un estante de abajo, debajo de lo que está listo para comer", "A temperatura ambiente"]'::jsonb,2,'Raw foods go below ready-to-eat foods so drips can''t contaminate them.','Lo crudo va abajo de lo listo para comer para que no gotee encima.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['eggs','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','labeling','You open a gallon of milk. What do you write on it?','Abres un galón de leche. ¿Qué le escribes?','["Nothing", "The guest count", "Your name only", "The open date or use-by date per policy"]'::jsonb,'["Nada", "Cuántos huéspedes hay", "Solo tu nombre", "La fecha en que se abrió o se debe usar según la política"]'::jsonb,3,'Date marking keeps you from serving old food.','Marcar la fecha evita servir comida vieja.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['labeling','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','labeling','What''s the ''first in, first out'' (FIFO) rule?','¿Qué es la regla de ''primero en entrar, primero en salir'' (PEPS)?','["Throw everything out daily", "Serve whatever is closest", "Use older stock before newer stock", "Use the newest first"]'::jsonb,'["Tirar todo cada día", "Servir lo que esté más cerca", "Usar lo más viejo antes que lo nuevo", "Usar lo más nuevo primero"]'::jsonb,2,'Put new deliveries behind older product.','Pon lo que llega nuevo detrás de lo que ya tenías.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','easy',array['labeling','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','What''s the difference between cleaning and sanitizing a counter?','¿Cuál es la diferencia entre limpiar y desinfectar una barra?','["Cleaning uses only sanitizer", "They''re the same", "Sanitizing is just rinsing", "Cleaning removes dirt; sanitizing reduces germs to safe levels"]'::jsonb,'["Limpiar es usar solo desinfectante", "Son lo mismo", "Desinfectar es solo enjuagar", "Limpiar quita la suciedad; desinfectar baja los gérmenes a niveles seguros"]'::jsonb,3,'Clean first, then sanitize — sanitizer can''t work through crumbs.','Primero limpia y luego desinfecta; el desinfectante no funciona sobre migajas.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['cleaning','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','How do you know your sanitizer bucket is the right strength?','¿Cómo sabes que tu cubeta de desinfectante tiene la concentración correcta?','["Check it with the test strips", "Smell it", "Add more until it burns", "It looks cloudy"]'::jsonb,'["Revisarla con las tiras de prueba", "Olerla", "Echar más hasta que arda", "Se ve turbia"]'::jsonb,0,'Too weak won''t kill germs; too strong can be unsafe.','Muy débil no mata gérmenes; muy fuerte puede ser peligroso.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['cleaning','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','illness','You woke up with vomiting and diarrhea. What should you do about your breakfast shift?','Amaneciste con vómito y diarrea. ¿Qué haces con tu turno de desayuno?','["Say nothing", "Tell your manager and don''t work with food", "Come in and wear gloves", "Work but skip the eggs"]'::jsonb,'["No decir nada", "Avisarle a tu gerente y no trabajar con alimentos", "Ir y usar guantes", "Trabajar pero no tocar huevos"]'::jsonb,1,'Food workers with vomiting or diarrhea must be excluded to protect guests.','Quien tiene vómito o diarrea no debe manejar alimentos, para proteger a los huéspedes.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['illness','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','waffle','The waffle maker beeps and a kid is reaching for it. What''s the best move?','La wafflera pita y un niño la quiere tocar. ¿Qué es lo mejor?','["Kindly step in, warn that it''s hot, and help them", "Unplug it for the day", "Yell at the kid", "Ignore it"]'::jsonb,'["Acercarte con amabilidad, avisar que está caliente y ayudarle", "Desconectarla todo el día", "Gritarle al niño", "Ignorarlo"]'::jsonb,0,'Waffle irons get very hot. A friendly assist prevents burns.','Las wafleras se calientan mucho. Ayudar con amabilidad evita quemaduras.','general hospitality best practice',array['breakfast']::text[],'role','easy',array['waffle','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','buffet','How should you refill a buffet pan that''s running low?','¿Cómo debes rellenar una charola del buffet que se está acabando?','["Stir old and new together", "Swap in a fresh pan — don''t pile new food on top of old", "Wait until it''s empty for 20 minutes", "Dump new food on top"]'::jsonb,'["Revolver lo viejo con lo nuevo", "Cambiar por una charola nueva; no echar comida nueva sobre la vieja", "Esperar 20 minutos vacía", "Echar la nueva encima"]'::jsonb,1,'Mixing old and new resets nothing — the old food is still old.','Mezclar lo viejo con lo nuevo no cambia nada; lo viejo sigue siendo viejo.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['buffet','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','buffet','Why keep sneeze guards in place over the buffet?','¿Por qué mantener las protecciones (sneeze guards) sobre el buffet?','["To hold signs", "For decoration", "They protect food from coughs, sneezes and hands", "To keep it warm"]'::jsonb,'["Para colgar letreros", "Para decorar", "Protegen la comida de tos, estornudos y manos", "Para mantenerla caliente"]'::jsonb,2,'Food on self-service display must be protected from contamination.','La comida de autoservicio debe estar protegida de contaminación.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['buffet','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','coffee','Why label decaf and regular coffee pots clearly?','¿Por qué rotular bien las jarras de café descafeinado y normal?','["For looks only", "Guests can taste the difference anyway", "Some guests can''t have caffeine for health reasons", "To use less coffee"]'::jsonb,'["Solo por apariencia", "Los huéspedes notan la diferencia de todos modos", "Algunos huéspedes no pueden tomar cafeína por salud", "Para usar menos café"]'::jsonb,2,'Clear labels are a simple way to keep guests safe and happy.','Las etiquetas claras son una forma sencilla de cuidar a los huéspedes.','general hospitality best practice',array['breakfast']::text[],'role','easy',array['coffee','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cleaning','When should you clean and sanitize the breakfast tables?','¿Cuándo debes limpiar y desinfectar las mesas del desayuno?','["Only at close", "Only if sticky", "After each guest leaves, plus at close", "Once a week"]'::jsonb,'["Solo al cerrar", "Solo si están pegajosas", "Cada vez que un huésped se va y al cerrar", "Una vez a la semana"]'::jsonb,2,'Fresh tables are one of the first things guests notice.','Las mesas limpias son de lo primero que notan los huéspedes.','general hospitality best practice',array['breakfast']::text[],'role','easy',array['cleaning','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pests','You see mouse droppings in the breakfast storage room. What do you do?','Ves excremento de ratón en la bodega del desayuno. ¿Qué haces?','["Set food on top", "Tell your manager right away and throw out any food that may be contaminated", "Keep serving", "Sweep it and say nothing"]'::jsonb,'["Poner comida encima", "Avisar al gerente de inmediato y tirar la comida que pudo contaminarse", "Seguir sirviendo", "Barrerlo y no decir nada"]'::jsonb,1,'Pests carry disease. The hotel needs to call pest control.','Las plagas transmiten enfermedades. El hotel debe llamar a control de plagas.','https://www.fda.gov/food/retail-food-protection/fda-food-code',array['breakfast']::text[],'role','med',array['pests','breakfast']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A guest wants to sit down inside Taco Bell on Wayzata Blvd at 11 p.m. What do you tell them?','Un huésped quiere sentarse dentro del Taco Bell de Wayzata Blvd a las 11 p. m. ¿Qué le dices?','["It''s only open for breakfast", "The dining room closes at 10 p.m. — the drive-thru runs late", "It closed at 6 p.m.", "It''s open inside 24 hours"]'::jsonb,'["Solo abre para el desayuno", "El comedor cierra a las 10 p. m.; el autoservicio abre hasta tarde", "Cerró a las 6 p. m.", "Adentro abre las 24 horas"]'::jsonb,1,'Taco Bell lists dine-in 7 a.m.–10 p.m.; drive-thru hours run much later, so tell them to check the app.','Taco Bell indica comedor de 7 a. m. a 10 p. m.; el autoservicio abre hasta mucho más tarde, que revisen la app.','https://locations.tacobell.com/mn/golden-valley/6620-wayzata-blvd.html',array['front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A late check-in wants a burger and a beer nearby around midnight. Which local spot is still open?','Un huésped que llegó tarde quiere una hamburguesa y una cerveza cerca a medianoche. ¿Qué lugar sigue abierto?','["Schuller''s Tavern on Country Club Drive (open until 1 a.m.)", "Benihana", "Liquor Barrel", "The Shops at West End food court"]'::jsonb,'["Schuller''s Tavern en Country Club Drive (abre hasta la 1 a. m.)", "Benihana", "Liquor Barrel", "El área de comida de West End"]'::jsonb,0,'Schuller''s lists 10 a.m.–1 a.m. every day.','Schuller''s abre de 10 a. m. a 1 a. m. todos los días.','https://schullerstavern.com/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A guest wants to try a ''Juicy Lucy'' near the hotel. Where''s a local classic?','Un huésped quiere probar una ''Juicy Lucy'' cerca del hotel. ¿Dónde hay un clásico local?','["Benihana", "Taco Bell", "Schuller''s Tavern, a family-owned roadhouse since 1929", "Walgreens"]'::jsonb,'["Benihana", "Taco Bell", "Schuller''s Tavern, un lugar familiar desde 1929", "Walgreens"]'::jsonb,2,'A Juicy Lucy is a cheese-stuffed burger — a Minnesota favorite Schuller''s is known for.','La Juicy Lucy es una hamburguesa rellena de queso, típica de Minnesota y famosa en Schuller''s.','https://westopolis.org/food-and-drink/schullers-tavern/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A group wants hibachi on a Saturday night. Until when is Benihana on Louisiana Ave open?','Un grupo quiere hibachi un sábado en la noche. ¿Hasta qué hora abre Benihana en Louisiana Ave?','["It''s closed Saturdays", "2 a.m.", "8 p.m.", "11 p.m. on Friday and Saturday"]'::jsonb,'["Cierra los sábados", "Hasta las 2 a. m.", "Hasta las 8 p. m.", "Hasta las 11 p. m. viernes y sábado"]'::jsonb,3,'Benihana lists Fri–Sat 11 a.m.–11 p.m. and Sun–Thu until 10 p.m.','Benihana abre viernes y sábado de 11 a. m. a 11 p. m., y de domingo a jueves hasta las 10 p. m.','https://www.benihana.com/locations/minneapolis/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A guest asks about Benihana on a Tuesday night. When does it close?','Un huésped pregunta por Benihana un martes en la noche. ¿A qué hora cierra?','["10 p.m.", "Midnight", "3 p.m.", "7 p.m."]'::jsonb,'["A las 10 p. m.", "A medianoche", "A las 3 p. m.", "A las 7 p. m."]'::jsonb,0,'Sunday through Thursday, Benihana is open until 10 p.m.','De domingo a jueves, Benihana abre hasta las 10 p. m.','https://www.benihana.com/locations/minneapolis/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A guest wants a cheaper bite and drinks at Benihana after a meeting on a weekday. What do you suggest?','Un huésped quiere algo más barato y bebidas en Benihana después de una junta entre semana. ¿Qué le sugieres?','["Late-night menu after midnight", "There are no specials", "Happy hour in the bar and lounge, Mon–Fri 3–6 p.m.", "Brunch on Sunday at 8 a.m."]'::jsonb,'["El menú de medianoche", "No hay promociones", "El happy hour en el bar, de lunes a viernes de 3 a 6 p. m.", "El brunch del domingo a las 8 a. m."]'::jsonb,2,'Benihana lists happy hour Monday–Friday 3–6 p.m. in the bar and lounge.','Benihana tiene happy hour de lunes a viernes de 3 a 6 p. m. en el bar.','https://www.benihana.com/locations/minneapolis/',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','What makes Benihana different from a regular restaurant?','¿Qué hace diferente a Benihana de un restaurante normal?','["It only serves breakfast", "It''s a drive-thru only", "A chef cooks your meal on a teppan grill right at your table", "It''s a buffet"]'::jsonb,'["Solo sirve desayuno", "Solo es autoservicio en carro", "Un chef cocina en una plancha teppan frente a tu mesa", "Es un buffet"]'::jsonb,2,'Good to know for groups and birthdays — it''s a show as well as dinner.','Es bueno saberlo para grupos y cumpleaños: es cena y espectáculo.','https://www.benihana.com/locations/minneapolis/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','liquor','A guest wants to buy a bottle of wine on Sunday afternoon. What are Liquor Barrel''s Sunday hours?','Un huésped quiere comprar una botella de vino el domingo en la tarde. ¿Qué horario tiene Liquor Barrel el domingo?','["Noon to midnight", "Closed all day", "9 a.m. to 10 p.m.", "11 a.m. to 6 p.m."]'::jsonb,'["Del mediodía a la medianoche", "Cierra todo el día", "De 9 a. m. a 10 p. m.", "De 11 a. m. a 6 p. m."]'::jsonb,3,'Liquor Barrel (7890 Olson Memorial Hwy) is open Sunday 11–6, matching Minnesota''s Sunday off-sale hours.','Liquor Barrel (7890 Olson Memorial Hwy) abre el domingo de 11 a 6, como lo permite la ley de Minnesota.','https://goldenvalleyliquorbarrel.com/contact/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','liquor','On a Wednesday, until what time can guests buy beer at Liquor Barrel?','Un miércoles, ¿hasta qué hora se puede comprar cerveza en Liquor Barrel?','["6 p.m.", "10 p.m.", "2 a.m.", "Midnight"]'::jsonb,'["Hasta las 6 p. m.", "Hasta las 10 p. m.", "Hasta las 2 a. m.", "Hasta la medianoche"]'::jsonb,1,'Mon–Sat 9 a.m.–10 p.m.; MN liquor stores can''t sell after 10 p.m.','De lunes a sábado de 9 a. m. a 10 p. m.; en MN las licorerías no venden después de las 10 p. m.','https://goldenvalleyliquorbarrel.com/contact/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','liquor','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','A guest wants to go to downtown St. Paul by bus. Which route from MOA or Terminal 1 goes there?','Un huésped quiere ir en autobús al centro de St. Paul. ¿Qué ruta desde el MOA o la Terminal 1 lo lleva?','["Route 54", "The Northstar train", "The Red Line to Apple Valley", "The hotel shuttle"]'::jsonb,'["La ruta 54", "El tren Northstar", "La Red Line a Apple Valley", "El shuttle del hotel"]'::jsonb,0,'Route 54 serves Mall of America, Terminal 1 and downtown St. Paul (Union Depot).','La ruta 54 pasa por el Mall of America, la Terminal 1 y el centro de St. Paul (Union Depot).','https://www.metrotransit.org/blue-line-station-maps',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','A guest wants to go to downtown St. Paul by bus. Which route from MOA or Terminal 1 goes there?','Un huésped quiere ir en autobús al centro de St. Paul. ¿Qué ruta desde el MOA o la Terminal 1 lo lleva?','["Route 54", "The Northstar train", "The hotel shuttle", "The Red Line to Apple Valley"]'::jsonb,'["La ruta 54", "El tren Northstar", "El shuttle del hotel", "La Red Line a Apple Valley"]'::jsonb,0,'Route 54 serves Mall of America, Terminal 1 and downtown St. Paul (Union Depot).','La ruta 54 pasa por el Mall of America, la Terminal 1 y el centro de St. Paul (Union Depot).','https://www.metrotransit.org/blue-line-station-maps',array['bartender','front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','local','About how far is downtown Minneapolis from the hotel?','¿Más o menos a qué distancia está el centro de Minneapolis del hotel?','["In another state", "Walking distance", "More than 40 miles", "Roughly 10 miles"]'::jsonb,'["En otro estado", "Se puede ir caminando", "A más de 40 millas", "Como a 10 millas"]'::jsonb,3,'Hilton lists downtown Minneapolis and downtown St. Paul each about 10 miles away.','Hilton indica que el centro de Minneapolis y el de St. Paul están a unas 10 millas cada uno.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','local','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','About how far is downtown Minneapolis from the hotel?','¿Más o menos a qué distancia está el centro de Minneapolis del hotel?','["In another state", "Walking distance", "More than 40 miles", "Roughly 10 miles"]'::jsonb,'["En otro estado", "Se puede ir caminando", "A más de 40 millas", "Como a 10 millas"]'::jsonb,3,'Hilton lists downtown Minneapolis and downtown St. Paul each about 10 miles away.','Hilton indica que el centro de Minneapolis y el de St. Paul están a unas 10 millas cada uno.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','local','About how far is downtown Minneapolis?','¿Más o menos a qué distancia está el centro de Minneapolis?','["Roughly 5 miles via I-394", "Walking distance", "In another state", "More than 40 miles"]'::jsonb,'["Como a 5 millas por la I-394", "Se puede ir caminando", "En otro estado", "A más de 40 millas"]'::jsonb,0,'The West End area is about 5 miles from downtown Minneapolis via I-394.','La zona de West End está a unas 5 millas del centro de Minneapolis por la I-394.','https://westopolis.org/wp-content/uploads/2025/02/WoP-Map2025_2.5.pdf',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','local','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
